import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, isActive } from '../claims/claimsQuery';
import type { Claim, ClaimStatus } from '../claims/claimsQuery';
import { GRADES, gradeOn, peopleQuery } from '../people/peopleQuery';
import { periodDue, periodsQuery } from '../periods/periodsQuery';
import { personDue, ratesQuery, sumDue } from '../rates/ratesQuery';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';

export const STATUSES: ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** How many of the sheet's claims have the status. */
export const statusCount = (claims: Claim[], status: ClaimStatus) => claims.filter((c) => c.status === status).length;

/**
 * The sheet at a glance, worked out from the same figures the lists show. Per grade: the people on it
 * today (retired people excluded), their due-totals added up, skipping n/a, and how many of them are active. Per period: its
 * due-total. Per status: how many claims have it.
 */
function Summary({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);

  const unretired = people.filter((p) => p.retiredFrom === null);

  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table data-testid="summary-grades">
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = unretired.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g} data-testid={`summary-grade-${g}`}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {sumDue(onGrade.map((p) => personDue(p, people, claims, rates, today, floor, late, cap)))}
                </td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => isActive(p.id, claims, people, today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`summary-period-${p.name}`}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDue(p, claims, people, rates, floor, late)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s} data-testid={`summary-status-${s}`}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{statusCount(claims, s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanel.fill({ order: 30, Component: Summary });
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

/** A holiday on the sheet (yyyy-mm-dd). */
export type Holiday = { date: string };

/** Under the sheet's key, so re-loading the sheet re-reads its holidays. */
export const holidaysKey = (sheetId: string) => [...sheetKey(sheetId), 'holidays'] as const;

export const holidaysQuery = (sheetId: string) => ({
  queryKey: holidaysKey(sheetId),
  queryFn: () => getJson<Holiday[]>(`/api/sheets/${encodeURIComponent(sheetId)}/holidays`),
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useUser } from '../session/useUser';
import { holidaysKey, holidaysQuery } from './holidaysQuery';
import type { Holiday } from './holidaysQuery';

/** The sheet's holidays, and the entry a date is added through. A claim's due-by, fixed when it is made, that falls on
 *  a holiday then on the list is the next day that is not one; a holiday added later leaves due-bys as they are. A date
 *  already on the list is refused. */
function Holidays({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const holidays = useQuery(holidaysQuery(sheetId));
  const [date, setDate] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: Holiday) =>
      postJson<Holiday>(`/api/sheets/${encodeURIComponent(sheetId)}/holidays`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: holidaysKey(sheetId) });
      setDate('');
    },
    onError: (e: Error) => setError(e.message || 'The holiday could not be added.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    once(() => save.mutateAsync({ date: date.trim() }));
  };

  return (
    <section data-testid="holidays">
      <h3>Holidays</h3>
      <form onSubmit={submit}>
        <label>
          Date{' '}
          <input
            data-testid="holiday-date"
            placeholder="yyyy-mm-dd"
            value={date}
            onChange={(e) => {
              setDate(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="holiday-add" disabled={save.isPending}>
          Add holiday
        </button>
        {error && <p data-testid="holiday-error">{error}</p>}
      </form>
      {holidays.isError && <p data-testid="holidays-load-error">Could not load the holidays.</p>}
      <ul data-testid="holidays-list">
        {(holidays.data ?? []).map((h) => (
          <li key={h.date} data-testid={`holiday-row-${h.date}`}>
            {h.date}
          </li>
        ))}
      </ul>
    </section>
  );
}

// Keyed by sheet, so a typed value or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 6.5,
  Component: ({ sheetId }) => <Holidays key={`holidays-${sheetId}`} sheetId={sheetId} />,
});
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}

